package com.jarvis.assistant.hud

import com.jarvis.assistant.core.Calculation
import com.jarvis.assistant.core.AppLanguage
import com.jarvis.assistant.voice.WakePhraseMatcher
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
import java.time.Instant
import java.util.Locale

class HudLogicTest {
    @Test fun batteryPercentUsesScaleAndRejectsInvalidSamples(){assertEquals(42,BatteryReading.percentage(84,200));assertEquals(100,BatteryReading.percentage(100,100));assertEquals(0,BatteryReading.percentage(0,100));assertNull(BatteryReading.percentage(-1,100));assertNull(BatteryReading.percentage(101,100));assertNull(BatteryReading.percentage(1,0))}
    @Test fun motionRespectsSystemReducedLowBatteryAndPowerSaver(){val s=HudSettings();assertEquals(0,HudMotion.fps(s.copy(reducedMotion=true),BatteryReading(),false,true));assertEquals(0,HudMotion.fps(s,BatteryReading(),false,false));assertEquals(8,HudMotion.fps(s,BatteryReading(9),false,true));assertEquals(12,HudMotion.fps(s,BatteryReading(19),false,true));assertEquals(8,HudMotion.fps(s,BatteryReading(99),true,true));assertEquals(30,HudMotion.fps(s.copy(animationProfile="cinematic"),BatteryReading(90),false,true))}
    @Test fun clockUsesZoneMinuteRolloverAndBothFormats(){val midnight=Instant.parse("2026-11-03T00:00:00Z").toEpochMilli();assertEquals("00:00",ClockDisplay.time(midnight,"UTC",Locale.US,"24",false));assertEquals("7:00 PM",ClockDisplay.time(midnight,"America/Guayaquil",Locale.US,"12",true));assertTrue(ClockDisplay.date(midnight,"America/Guayaquil",Locale.US).contains("2 November"));assertEquals("23:59",ClockDisplay.time(midnight-60_000,"UTC",Locale.US,"system",true))}
    @Test fun clockHonorsDstAndSelectedLocale(){val after=Instant.parse("2026-03-08T07:00:00Z").toEpochMilli();assertEquals("03:00",ClockDisplay.time(after,"America/New_York",Locale.US,"24",true));assertEquals("01:59",ClockDisplay.time(after-60_000,"America/New_York",Locale.US,"24",true));assertTrue(ClockDisplay.date(after,"UTC",Locale.forLanguageTag("es")).contains("domingo"));assertNotEquals(ClockDisplay.date(after,"UTC",Locale.US),ClockDisplay.date(after,"UTC",Locale.forLanguageTag("fa")))}
    @Test fun pcmMeterReadsActualSignedSamplesAndClearsSilence(){assertEquals(0f,PcmLevel.pcm16(ByteArray(20),20),0f);assertEquals(.5f,PcmLevel.pcm16(byteArrayOf(0,64,0,-64),4),.0001f);assertEquals(0f,PcmLevel.pcm16(byteArrayOf(1),1),0f);assertEquals(.5f,PcmLevel.floats(floatArrayOf(.5f,-.5f)),.001f);assertEquals(0f,PcmLevel.floats(floatArrayOf(Float.NaN)),0f)}
    private fun weather()=JSONObject("""{"current":{"time":"2026-11-02T13:15","temperature_2m":21.4,"apparent_temperature":20.2,"relative_humidity_2m":65,"wind_speed_10m":8.1,"weather_code":2},"daily":{"sunrise":["2026-11-02T06:00"],"sunset":["2026-11-02T18:00"]},"hourly":{"time":["2026-11-02T12:00","2026-11-02T13:00"],"precipitation_probability":[12,27]}}""")
    @Test fun weatherUsesObservedFieldsAndMatchingHour(){val r=WeatherRepository.parse(weather(),"Test fixture",100);assertEquals(21.4,r.temperatureC!!,.001);assertEquals(65,r.humidity);assertEquals(27,r.precipitationProbability);assertEquals("2026-11-02T18:00",r.sunset);assertEquals(100,r.fetchedAt)}
    @Test fun weatherMissingMeasurementsStayMissing(){val r=WeatherRepository.parse(JSONObject("""{"current":{"time":"2026-11-02T00:00","temperature_2m":null}}"""),"Fixture",1);assertNull(r.temperatureC);assertNull(r.humidity);assertNull(r.precipitationProbability);assertNull(r.sunrise)}
    @Test(expected=IllegalStateException::class)fun weatherRejectsProviderErrors(){WeatherRepository.parse(JSONObject("""{"error":true,"reason":"provider failure"}"""),"Fixture",1)}
    @Test(expected=IllegalStateException::class)fun weatherRejectsMissingTimestamp(){WeatherRepository.parse(JSONObject("""{"current":{"temperature_2m":10}}"""),"Fixture",1)}
    @Test fun cacheExpiryAndClockRollbackAreExplicit(){val r=WeatherRepository.parse(weather(),"Fixture",1000);assertFalse(WeatherRepository.stale(r,1001));assertTrue(WeatherRepository.stale(r,1000+WeatherRepository.MAX_AGE));assertTrue(WeatherRepository.stale(r,999));assertTrue(WeatherRepository.stale(null,1000))}
    @Test fun codexIsTriggerOnlyAndActionCannotReplay(){var now=0L;val auth=AuthorizationCoordinator({now});assertNull(auth.codex());val r=auth.begin("Delete one note");assertFalse(auth.complete(r.id,true));auth.awaiting();auth.codex();assertFalse(auth.complete("another action",true));assertTrue(auth.complete(r.id,true));assertFalse(auth.complete(r.id,true));assertEquals(AuthorizationStatus.AUTHORIZED,auth.current()!!.status)}
    @Test fun authorizationCancelExpiryAndReplacementAreIsolated(){var now=0L;val auth=AuthorizationCoordinator({now},100);val old=auth.begin("First");auth.codex();val next=auth.begin("Second");assertFalse(auth.complete(old.id,true));auth.codex();auth.cancel();assertFalse(auth.complete(next.id,true));val exp=auth.begin("Third");auth.codex();now=100;assertFalse(auth.complete(exp.id,true));assertEquals(AuthorizationStatus.EXPIRED,auth.current()!!.status)}
    @Test fun codeWordAndWakePhrasesStaySeparate(){assertTrue(AuthorizationCoordinator.isCodex("Códex!"));assertFalse(AuthorizationCoordinator.isCodex("Codex delete all"));assertNull(WakePhraseMatcher.extractCommand("Codex",AppLanguage.EN));assertEquals("open youtube",WakePhraseMatcher.extractCommand("Hey Jarvis open YouTube",AppLanguage.EN));assertEquals("",WakePhraseMatcher.extractCommand("Oye Jarvis",AppLanguage.ES));assertEquals("ساعت چنده",WakePhraseMatcher.extractCommand("هی جارویس ساعت چنده",AppLanguage.FA))}
    @Test fun calculationSupportsPrecedenceParenthesesAndPersianDigits(){assertEquals("14",Calculation.requested("calculate 2 + 3 * 4"));assertEquals("-20",Calculation.evaluate("-(2+3)*4"));assertEquals("4.5",Calculation.evaluate("۹ ÷ ۲"));assertNull(Calculation.requested("how to calculate taxes"))}
    @Test fun calculationRejectsCodeAndUnboundedInput(){for(s in listOf("1/0","Runtime.exec()","2**3","(".repeat(30)+"1"+")".repeat(30),"1+")){assertTrue(runCatching{Calculation.evaluate(s)}.isFailure)}}
}
